def create_signing_round(
    message: bytes,
    signer_ids: Iterable[int],
    nonce_commitments: Iterable[SigningNonceCommitment],
    dkg_result: SigningDKGResult,
) -> SigningRound:
    """Assemble the round-one commitments into a fixed :class:`SigningRound`.

    ``signer_ids`` must be unique DKG participants, strictly increasing once
    sorted, and number at least ``threshold``; ``nonce_commitments`` must
    contain exactly one round-one commitment per signer, whose ``R_i`` values
    must be non-identity elements of the order-``field_prime`` subgroup. The
    aggregate ``R`` is the product of every ``R_i`` and the challenge binds
    the tag, the message digest, ``Y``, ``R`` and the canonical signer-id
    list. Malformed arguments raise TypeError/ValueError; a commitment that
    is structurally valid but reuses a value or belongs elsewhere is an
    illegal input here (duplicate ``R_i`` values are rejected to stop nonce
    commitments being copied between signers).
    """
    if not isinstance(message, bytes):
        raise TypeError("message must be bytes")
    result, public_key, field_prime, group_prime, _generator = _check_signing_setup(dkg_result)

    ids = list(signer_ids)
    if not ids:
        raise ValueError("at least one signer is required")
    for signer_id in ids:
        if not isinstance(signer_id, int) or isinstance(signer_id, bool):
